import java.util.Arrays;
import java.util.Scanner;

public class LuckyTickets {
    private static final int MOD = 998244353;
    private static final int ROOT = 15311432;
    private static final int INVROOT = 469870224;

    private static int reverseBits(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    private static long modularInverse(int a) {
        return modularExponentiation(a, MOD - 2);
    }

    private static long modularExponentiation(int base, int exp) {
        long result = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return result;
    }

    private static void ntt(long[] arr, int logN, boolean invert) {
        int baseRoot = invert ? INVROOT : ROOT;
        long root = modularExponentiation(baseRoot, (int) Math.pow(2, 23 - logN));
        long[] roots = new long[logN];
        roots[logN - 1] = root;
        for (int i = logN - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        for (int s = 0; s < logN; s++) {
            int len = 1 << s;
            for (int start = 0; start < arr.length; start += 2 * len) {
                long curRoot = 1;
                for (int j = start; j < start + len; j++) {
                    long t = (curRoot * arr[j + len]) % MOD;
                    long u = arr[j];
                    arr[j] = (u + t) % MOD;
                    arr[j + len] = (u - t) % MOD;
                    curRoot = (roots[s] * curRoot) % MOD;
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
        }
        Arrays.sort(nums);
        int minSize = n * nums[m - 1] + 2;
        int logSize = 0;
        int size = 1;
        while (size < minSize) {
            size <<= 1;
            logSize++;
        }
        long[] array = new long[size];
        for (int num : nums) {
            array[reverseBits(num, logSize)] = 1;
        }
        ntt(array, logSize, false);
        for (int i = 0; i < size; i++) {
            array[i] = powMod((int) array[i], n);
        }
        long[] tempArray = new long[size];
        for (int i = 0; i < size; i++) {
            tempArray[reverseBits(i, logSize)] = array[i] % MOD;
        }
        array = tempArray;
        ntt(array, logSize, true);
        long totalSum = 0;
        for (int i = 0; i < size; i++) {
            totalSum = (totalSum + array[i] * array[i]) % MOD;
        }
        long invSize = modularInverse(size);
        System.out.println((((totalSum * invSize) % MOD) * invSize) % MOD);
    }
}
